# Lab CASO-LIM-021 — render_kpi reutilizable
# TODO: la plantilla debe incluir n={{ n }}
from jinja2 import Template

def render_kpi(ctx):
 return Template("{{ region }}: {{ median }} PEN").render(**ctx)
print(render_kpi({"region": "Madrid", "median": 22.5, "n": 18}))

